<!-- This file is generated by AI. -->
<!--
  场景配音卡: 在场景文件旁边就地生成配音 —— 左边是 Monaco (只读 + 整行高亮), 右边是当前
  对话的配音参数与历史 (试听 / 生成 / 应用)。「应用」会把 `vocal` 参数写回脚本那一行。

  * **光标停在哪一行由编辑器派生, 不存字段**: 存字段就会出现"切卡后停在上一张卡的行号"
    (全局光标被新文档继承)。这里一律从 `appStore.cursor` + 当前文档路径算。
  * **磁盘被外部改动要弹冲突裁决**, 而不是悄悄覆盖 —— 配音卡会让用户长时间停在一个文件上,
    期间在别处改它的概率不低。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->
<script lang="ts">
  import { onMount, untrack } from 'svelte';

  import { fs } from '../lib/fs';
  import { appStore } from '../state/store.svelte';
  import { voiceController } from '../voice/controller';
  import { dialogueAtLine } from '../voice/types';
  import { isSceneInVoiceMode } from '../voice/mode';
  import Button from './Button.svelte';
  import SceneConflictDialog from './SceneConflictDialog.svelte';
  import SentenceVoicePanel from './SentenceVoicePanel.svelte';
  import VoiceTakeList from './VoiceTakeList.svelte';
  import CodeEditor from './CodeEditor.svelte';

  /** 磁盘变更检测间隔。轮询而不是监听文件: 场景文件可能被任意外部程序改写, 监听会漏掉原子替换式的保存。 */
  const DISK_CHECK_MS = 3000;

  let { docPath }: { docPath: string } = $props();

  const doc = $derived(appStore.documents.find((item) => item.path === docPath) ?? null);
  /** 队列/卡片变化的令牌: 控制器就地改内部状态, 靠它驱动重算。 */
  const tick = $derived(appStore.voiceTick);

  /*
   * 卡片从 **store** 里读, 而不是走 `voiceController.getCard()`。
   *
   * 控制器的 `cards` 是普通 Map, 就地改它不触发任何重算; 它每次同步都会把**一份新的 Map**
   * 写进 store (`setSceneVoiceEditors`), 所以读 store 这一份才有响应性。
   */
  const card = $derived(appStore.sceneVoiceEditors.get(docPath) ?? null);

  const characters = $derived(appStore.voiceCharacters);

  /**
   * 当前光标停在哪一段对话上。
   *
   * 从全局光标 + 本卡路径派生 (**不存字段**): 存字段会在切卡时把上一张卡的行号继承过来,
   * 于是配音卡一挂载就选中错误的行、甚至因为该行不是对话而清空整张卡。
   *
   * 但**切回卡片时会有一小段没有光标的窗口** —— 编辑器还没挂载/上报, `appStore.cursor`
   * 还是 null。这时回退用卡片自己记下的 `cursorLine`, 让面板立刻有内容而不是空白一片,
   * 等编辑器上报后自然切回精确值。
   */
  const liveLine = $derived(appStore.cursor && appStore.cursor.path === docPath ? appStore.cursor.line - 1 : null);
  const cursorLine = $derived.by(() => {
    // 记忆值来自普通对象字段 (就地改), 因此这里也要读令牌
    void appStore.voiceTick;
    return liveLine ?? card?.cursorLine ?? null;
  });

  /**
   * 当前这一句对话。
   *
   * ⚠️ **必须读 `appStore.voiceTick`**: `refreshCard()` 只换 `card.dialogues` 字段而不换 `card`
   * 对象, 且 `sceneVoiceEditors` 是 **Map** (Svelte 不代理 Map 的内容), 于是 `card` 重算后值没变,
   * `$derived` 的 `===` 传播规则就不通知下游, `dialogue` 会一直返回旧对象 (「应用」后「移除」仍禁用)。
   */
  const dialogue = $derived.by(() => {
    void appStore.voiceTick;
    return card && cursorLine !== null ? dialogueAtLine(card.dialogues, cursorLine) : null;
  });

  /** 已经落到磁盘的历史条数 (光标不在对话上时给「重新对齐」按钮用) —— 同样读令牌 */
  const historyCount = $derived.by(() => {
    void appStore.voiceTick;
    return card?.history.length ?? 0;
  });

  /**
   * 解析阶段与磁盘冲突的错误。
   *
   * 生成/试听的错误归左栏面板自己管 (那里离按钮更近), 这里只放"卡片还没解析出来"这类
   * 整卡级别的失败。
   */
  let error = $state<string | null>(null);

  /*
   * 磁盘冲突裁决。
   *
   * `dismissedHash` 记住"用户按了 Esc 的那个磁盘状态": 变更检测每隔几秒跑一次, 不记的话
   * Esc 等于没按、对话框立刻弹回来。以**全文哈希**为键 —— 只用预览那一小段的话, 外部改的
   * 若是第 13 行之后的内容, 哈希不变, 于是**再也不提示冲突**, 用户的改动会被静默丢掉。
   */

  let conflict = $state<{ preview: string | null; hash: string } | null>(null);
  let dismissedHash = $state<string | null>(null);

  onMount(() => {
    void syncCard();
  });

  /**
   * 检测磁盘是否被外部改动 + 回到窗口时补一次。
   *
   * 只在这一张卡是**当前活动文档**时检查: 后台选项卡的文件被外部改动不必打断用户,
   * 等他切回来看就来得及。
   */
  $effect(() => {
    const isActive = isSceneInVoiceMode(docPath);
    if (!isActive) return;

    let disposed = false;
    const check = async (): Promise<void> => {
      if (disposed) return;
      const changed = await voiceController.checkDiskChange(docPath);
      if (disposed || !changed) return;

      let preview: string | null = null;
      let hash: string | null = null;
      try {
        const content = await fs.readTextLossy(docPath);
        /*
         * 预览只取开头几行 (对话框里放不下), 但**忽略键必须用全文哈希**: 用预览哈希会漏掉
         * "外部只改了第 13 行之后"的情况 —— 预览没变 -> 哈希没变 -> 被当成"已经忽略过的那一份"
         * -> **再也不提示冲突**, 用户手改的内容会被悄悄覆盖。全文哈希才是正确的语义:
         * 同一份磁盘内容只问一次, 内容真的变了一定再问。
         */
        hash = hashOf(content);
        preview = content.split(/\r?\n/).slice(0, 12).join('\n');
      } catch {
        // 读不到就只给文字说明, 不发预览 (此时「加载磁盘内容」会保持禁用)
      }
      if (disposed) return;

      // 读不到内容时退化成"每次都提示": 宁可多问一次, 也不要静默放过一次冲突
      if (hash !== null && dismissedHash === hash) return;
      conflict = { preview, hash: hash ?? `unreadable:${Date.now()}` };
    };

    void check();
    const timer = setInterval(() => void check(), DISK_CHECK_MS);
    const onFocus = () => void check();
    window.addEventListener('focus', onFocus);
    return () => {
      disposed = true;
      clearInterval(timer);
      window.removeEventListener('focus', onFocus);
    };
  });

  /** 与控制器一致的轻量内容哈希 (只用于比较"是不是同一份磁盘内容")。 */
  function hashOf(text: string): string {
    let value = 0x811c9dc5;
    const normalized = text.replace(/\r\n/g, '\n');
    for (let index = 0; index < normalized.length; index += 1) {
      value ^= normalized.charCodeAt(index);
      value = Math.imul(value, 0x01000193);
    }
    return (value >>> 0).toString(16);
  }

  /**
   * 文档内容变化 -> 重新解析对话 (卡片随内容更新)。
   *
   * 不依赖 `voiceTick`: 那个令牌只在任务生命周期里自增, 与"用户改了文本"无关。
   * 这里的触发条件是 `doc.content` 本身。
   */
  $effect(() => {
    const content = doc?.content;
    const path = docPath;
    if (content === undefined) return;
    void (async () => {
      const current = voiceController.getCard(path);
      if (!current) return;
      await voiceController.refreshCard(path, content);
    })();
  });

  /**
   * 光标位置变化 -> 把"当前是哪一句"记进卡片。
   *
   * 这份记忆的唯一用途是**切走再切回**的那一小段窗口: 编辑器刚挂载、还没上报光标
   * (`liveLine === null`), 界面靠它立刻显示上次那一句, 而不是空白。
   *
   * * **只在编辑器真的报了光标时写** (`liveLine !== null`): 否则会拿"记忆值"回写记忆, 一旦它
   *   已经是 null 就永远写不进去;
   * * **写的是命中的那一句的行号** (`dialogue?.line`), 没命中就写 null —— 存的不是光标行, 于是
   *   文本被改动、行号整体位移之后也还能对上那一刻的语句;
   * * **卸载时绝不清空** (本组件不注册任何卸载清理): 它是跨导航的状态, 清掉之后切回来时编辑器
   *   尚未上报, 回退值已是 null -> 面板落到"光标未落在对话语句上"。
   */
  $effect(() => {
    const line = liveLine;
    if (line === null) return;
    // 卡片可能是后建好的 (`onMount` 里的 `openCard` 是异步的): 读 tick 建立依赖, 同步后补写一次
    void tick;
    voiceController.setCursorLine(docPath, dialogue?.line ?? null);
  });

  async function syncCard(): Promise<void> {
    const current = untrack(() => doc);
    if (!current) return;
    try {
      const existing = voiceController.getCard(docPath);
      if (!existing) {
        await voiceController.openCard(docPath, docPath, current.content, '');
      } else {
        await voiceController.refreshCard(docPath, current.content);
      }
    } catch (e) {
      error = String(e);
    }
  }

  /*
   * 离开配音卡时**不做任何清理**: 卡片不销毁 (任务还在队列里跑, 历史也已落盘), 那张
   * `card.cursorLine` 记忆也不清空 —— 它是跨导航状态, 切回来时要靠它立刻显示上次那一句
   * (上面写记忆的那个 effect 依赖它作回退值)。在这里加一句 `setCursorLine(docPath, null)`
   * 就会造成"切回来选中丢失"。
   */
</script>

<!--
  布局沿用既有类名: 编辑器在上, 固定高度的配音面板在下, 面板内左右分栏
  (左 = 操作台, 右 = 这一句的记录)。
-->
<div class="scene-voice">
  <div class="scene-voice-editor">
    {#if doc}
      <CodeEditor {doc} readOnly highlightLine={dialogue ? { line: dialogue.line, count: dialogue.lineCount } : null} />
    {/if}
  </div>

  <div class="scene-voice-panel">
    {#if !card}
      <div class="scene-voice-empty">
        <p>正在解析场景…</p>
        {#if error}
          <p class="prompt-error">{error}</p>
        {/if}
      </div>
    {:else if dialogue}
      <div class="scene-voice-split">
        <SentenceVoicePanel cardId={docPath} {dialogue} {characters} />
        <VoiceTakeList cardId={docPath} line={dialogue.line} />
      </div>
    {:else}
      <div class="scene-voice-empty">
        <p>光标未落在对话语句上。</p>
        <p class="scene-voice-hint">将光标移动到任意一句对话（旁白或人物台词）上，即可在此配置并生成配音。</p>
        {#if historyCount > 0}
          <Button appearance="subtle" icon="ArrowSync" onclick={() => void voiceController.realignCard(docPath)}>
            重新对齐 {historyCount} 条配音记录
          </Button>
        {/if}
      </div>
    {/if}
  </div>

  {#if conflict}
    <SceneConflictDialog
      scenePath={docPath}
      diskPreview={conflict.preview}
      inRepository={appStore.gitStatus?.initialized === true}
      onResolved={() => (conflict = null)}
      onDismiss={() => {
        dismissedHash = conflict?.hash ?? null;
        conflict = null;
      }}
    />
  {/if}
</div>
